// Arte generico, por si algun dia recibirDanio() llega con una causa
// que todavia no tiene su propio bloque.
static void mostrarArteGenerico(const std::string& causa)
{
    Console::ForegroundColor = ConsoleColor::DarkRed;
    Console::WriteLine("------------------------------------------------------------------------");
    Console::WriteLine();
    std::cout << "                    [ ASCII " << causa << " - PLACEHOLDER ]" << std::endl;
    Console::WriteLine();
    Console::WriteLine("------------------------------------------------------------------------");
    Console::ResetColor();
}

void EscenaMuerte(const std::string& causa)
{
    std::string mensaje;

    // ---- ASCII ART DE ARRIBA (segun la causa) ----
    if (causa == "tronco") mostrarArteTronco();
    else if (causa == "pinchos") mostrarArtePinchos();
    else if (causa == "lobo") mostrarArteLobo();
    else mostrarArteGenerico(causa);

    Console::WriteLine();

    // ---- MOTIVO DE LA MUERTE ----
    Console::ForegroundColor = ConsoleColor::Red;
    Console::WriteLine("> CAPERUCITA HA CAIDO...");
    Console::ForegroundColor = ConsoleColor::Gray;

    std::cout << "  " << mensaje << std::endl;
    Console::WriteLine();

    // ---- ASCII ART DE ABAJO (la misma causa) ----
    if (causa == "tronco") mostrarArteTronco();
    else if (causa == "pinchos") mostrarArtePinchos();
    else if (causa == "lobo") mostrarArteLobo();
    else mostrarArteGenerico(causa);

    Console::WriteLine();

    // ---- PROMPT DE CONTINUAR ----
    Console::ForegroundColor = ConsoleColor::DarkGray;
    Console::WriteLine("[ Presiona cualquier tecla para continuar... ]");
    Console::ResetColor();

    Console::ReadKey(true);
    Console::Clear();
}
